'use client'

import Link from 'next/link'
import { useEffect, useMemo, useRef, useState } from 'react'
import { useSearchParams } from 'next/navigation'
import { parseArbiterSchedule } from '@/lib/parser'
import type { ParsedGameRow, Season, Sport } from '@/types'

type TeamRecord = { id:string; team_name:string; sport_id:string; level:string|null; active:boolean|null; school:{id:string;school_name:string;slug:string;alias:string|null}|null }
type TeamSeasonRecord = { team_id:string; season_id:string; active_for_season:boolean|null }
type DiffKind = 'unchanged'|'new'|'date_changed'|'time_changed'|'location_changed'|'status_changed'|'details_changed'|'possible_removed'|'external_review'|'conflict'
type NewConfidence = 'confirmed'|'single_source'|'cross_source_conflict'|'external'
type ReconciliationStatus = 'two_source_agree'|'source_conflict'|'single_source'
type SourceObservation = { team_id:string; team_name:string; game_time:string|null; status:string|null }
type DiffRow = { key:string; kind:DiffKind; safe:boolean; existing_game_id:string|null; incoming:any|null; existing:any|null; changes:Array<{field:string;before:string|number|boolean|null;after:string|number|boolean|null}>; note?:string; new_confidence?:NewConfidence; cross_source_count?:number; cross_source_team_ids?:string[]; reconciliation_required?:boolean; reconciliation_status?:ReconciliationStatus; source_observations?:SourceObservation[] }
type CompareResult = { success:boolean; scanned_at:string; existing_count:number; incoming_count:number; safe_count:number; detected_change_count?:number; bulk_safe_change_count?:number; new_game_count?:number; review_count:number; counts:Record<string,number>; apply_allowed?:boolean; safety_reasons?:string[]; normalization?:string; diffs:DiffRow[] }
type ScanOutput = { comparison:CompareResult; rows:ParsedGameRow[]; resolvedUrl:string; arbiterTeamName?:string|null }
type BatchStatus = 'clean'|'updated'|'confirmed'|'new'|'review'|'conflict'|'blocked'|'failed'
type BatchRow = { teamId:string; teamName:string; sportName:string; status:BatchStatus; unchanged:number; updates:number; confirmedNew:number; singleSourceNew:number; conflicts:number; review:number; message?:string; output?:ScanOutput }
type DiffSummary = { unchanged:number; verifiedUpdates:number; confirmedNew:number; singleSourceNew:number; sourceConflicts:number; waitingSecondSource:number; dateReschedule:number; venue:number; possibleRemoved:number; matchDetails:number; otherReview:number }
type QueueFilter = 'all'|'clean'|'verified'|'confirmed_new'|'single_source'|'conflict'|'review'|'waiting'|'date'|'venue'|'removed'|'details'|'blocked'|'failed'
type QueueCategory = Exclude<QueueFilter,'all'|'clean'|'review'|'blocked'|'failed'>
type QueueItem = { key:string; category:QueueCategory; row:BatchRow; diff:DiffRow }
interface Props { teams:TeamRecord[]; sports:Sport[]; seasons:Season[]; teamSeasons:TeamSeasonRecord[] }

const TEAM_URLS_KEY='sectionx.schedule-sync.team-urls.v2'
const SCHOOL_URLS_KEY='sectionx.schedule-sync.school-urls.v2'

function normalizeSport(value:string|null|undefined){return String(value||'').toLowerCase().replace(/\([^)]*\)/g,' ').replace(/[^a-z0-9]+/g,' ').replace(/\s+/g,' ').trim()}
function schoolUrlFromScheduleUrl(value:string){try{const u=new URL(value);const id=u.searchParams.get('activeEntityId')||u.searchParams.get('entityId');return id?`https://arbiterlive.com/Teams?entityId=${id}`:null}catch{return null}}
function wait(ms:number){return new Promise(resolve=>setTimeout(resolve,ms))}
function formatTime(value:any){const raw=String(value||'').trim();const match=raw.match(/^(\d{1,2}):(\d{2})/);if(!match)return raw||'TBD';let h=Number(match[1]);const m=match[2];const ampm=h>=12?'PM':'AM';h=h%12||12;return `${h}:${m} ${ampm}`}
function normalizeObservedTime(value:any){const raw=String(value||'').trim();const match=raw.match(/^(\d{1,2}):(\d{2})/);return match?`${String(Number(match[1])).padStart(2,'0')}:${match[2]}`:raw.toLowerCase()}
function normalizeObservedStatus(value:any){const raw=String(value||'').trim().toLowerCase();if(!raw)return 'scheduled';if(raw==='ppd'||raw==='postponed')return 'postponed';if(raw==='cancelled'||raw==='canceled')return 'canceled';if(raw==='in progress'||raw==='live')return 'live';return raw}
function observationSignature(game:any){return `${normalizeObservedTime(game?.game_time)}|${normalizeObservedStatus(game?.status)}`}
function pairKey(game:any,sportId:string){if(!game?.home_team_id||!game?.away_team_id)return null;return `${sportId}|${[game.home_team_id,game.away_team_id].sort().join('|')}`}
function datedPairKey(game:any,sportId:string){const pair=pairKey(game,sportId);return pair&&game?.game_date?`${pair}|${game.game_date}`:null}
function isTimeStatusOnlyDiff(diff:DiffRow){return diff.kind==='unchanged'||(diff.changes.length>0&&diff.changes.every(change=>change.field==='game_time'||change.field==='status'))}
function issueKey(diff:DiffRow,fallback:string){return diff.existing_game_id||`${fallback}|${diff.kind}|${diff.incoming?.game_date||diff.existing?.game_date||diff.key}`}
function summarizeDiffs(diffs:DiffRow[]):DiffSummary{
  const verified=new Set(diffs.filter(d=>d.safe&&d.kind!=='unchanged'&&d.existing_game_id).map(d=>d.existing_game_id as string))
  const unchanged=diffs.filter(d=>d.kind==='unchanged'&&d.reconciliation_status!=='source_conflict'&&d.safe).length
  const confirmedNew=diffs.filter(d=>d.kind==='new'&&d.new_confidence==='confirmed').length
  const singleSourceNew=diffs.filter(d=>(d.kind==='new'&&d.new_confidence!=='confirmed'&&d.new_confidence!=='cross_source_conflict')||d.kind==='external_review').length
  const sourceConflicts=diffs.filter(d=>d.kind==='conflict'||d.new_confidence==='cross_source_conflict'||d.reconciliation_status==='source_conflict').length
  const waitingSecondSource=diffs.filter(d=>!d.safe&&d.reconciliation_status==='single_source'&&d.kind!=='new'&&d.kind!=='external_review').length
  const dateReschedule=diffs.filter(d=>!d.safe&&d.kind==='date_changed'&&d.reconciliation_status!=='source_conflict'&&d.reconciliation_status!=='single_source').length
  const venue=diffs.filter(d=>!d.safe&&d.kind==='location_changed'&&d.reconciliation_status!=='source_conflict'&&d.reconciliation_status!=='single_source').length
  const possibleRemoved=diffs.filter(d=>!d.safe&&d.kind==='possible_removed').length
  const explicitlyCounted=new Set<DiffRow>()
  for(const d of diffs){if(d.kind==='new'||d.kind==='external_review'||d.kind==='possible_removed'||d.kind==='date_changed'||d.kind==='location_changed'||d.reconciliation_status==='source_conflict'||d.reconciliation_status==='single_source')explicitlyCounted.add(d)}
  const matchDetails=diffs.filter(d=>!d.safe&&!explicitlyCounted.has(d)&&d.kind!=='unchanged').length
  return {unchanged,verifiedUpdates:verified.size,confirmedNew,singleSourceNew,sourceConflicts,waitingSecondSource,dateReschedule,venue,possibleRemoved,matchDetails,otherReview:waitingSecondSource+dateReschedule+venue+possibleRemoved+matchDetails}
}
function syncComparisonCounts(comparison:CompareResult){const s=summarizeDiffs(comparison.diffs);comparison.safe_count=comparison.diffs.filter(d=>d.safe).length;comparison.bulk_safe_change_count=s.verifiedUpdates;comparison.review_count=comparison.diffs.filter(d=>!d.safe).length;comparison.counts={...comparison.counts,unchanged:s.unchanged};return s}
function diffLabel(diff:DiffRow){if(diff.reconciliation_status==='source_conflict')return'SOURCE DISAGREEMENT';if(diff.reconciliation_status==='two_source_agree'&&diff.kind!=='unchanged')return'2-SOURCE CONFIRMED UPDATE';if(diff.reconciliation_status==='single_source'&&diff.kind!=='unchanged')return'WAITING FOR SECOND SOURCE';if(diff.kind==='new'){if(diff.new_confidence==='confirmed')return'CONFIRMED NEW GAME';if(diff.new_confidence==='cross_source_conflict')return'NEW GAME SOURCE CONFLICT';return'SINGLE-SOURCE NEW GAME'}return({unchanged:'UNCHANGED',date_changed:'DATE / RESCHEDULE REVIEW',time_changed:'TIME CHANGED',location_changed:'VENUE CHANGE REVIEW',status_changed:'STATUS CHANGED',details_changed:'MATCH / DETAILS REVIEW',possible_removed:'POSSIBLE REMOVED',external_review:'EXTERNAL GAME REVIEW',conflict:'MATCH / ORIENTATION CONFLICT'}as Record<string,string>)[diff.kind]||diff.kind.toUpperCase()}
function diffColor(diff:DiffRow){if(diff.reconciliation_status==='source_conflict')return'#f87171';if(diff.reconciliation_status==='two_source_agree')return'#4ade80';if(diff.reconciliation_status==='single_source')return'#60a5fa';if(diff.kind==='unchanged')return'#4ade80';if(diff.kind==='new'&&diff.new_confidence==='confirmed')return'#4ade80';if(diff.kind==='new'&&diff.new_confidence==='single_source')return'#60a5fa';if(['possible_removed','external_review','conflict'].includes(diff.kind)||diff.new_confidence==='cross_source_conflict')return'#f87171';return'#fbbf24'}
function statusColor(status:BatchStatus){if(status==='clean'||status==='confirmed')return'#4ade80';if(status==='updated')return'#fbbf24';if(status==='new')return'#60a5fa';return'#f87171'}
function queueCategory(diff:DiffRow):QueueCategory|null{if(diff.safe&&diff.kind!=='unchanged'&&diff.existing_game_id)return'verified';if(diff.kind==='new'&&diff.new_confidence==='confirmed')return'confirmed_new';if(diff.kind==='new'&&diff.new_confidence!=='cross_source_conflict'||diff.kind==='external_review')return'single_source';if(diff.kind==='conflict'||diff.new_confidence==='cross_source_conflict'||diff.reconciliation_status==='source_conflict')return'conflict';if(!diff.safe&&diff.reconciliation_status==='single_source')return'waiting';if(!diff.safe&&diff.kind==='date_changed')return'date';if(!diff.safe&&diff.kind==='location_changed')return'venue';if(!diff.safe&&diff.kind==='possible_removed')return'removed';if(!diff.safe&&diff.kind!=='unchanged')return'details';return null}
function queueLabel(filter:QueueFilter){return({all:'All Issues',clean:'Clean Teams',verified:'Verified Updates',confirmed_new:'Confirmed New',single_source:'Single Source',conflict:'Source Conflicts',review:'Review Queue',waiting:'Waiting 2nd Source',date:'Date / Reschedule',venue:'Venue',removed:'Possible Removed',details:'Match / Details',blocked:'Blocked',failed:'Failed'}as Record<QueueFilter,string>)[filter]}

export default function ScheduleSync({teams,sports,seasons,teamSeasons}:Props){
  const searchParams=useSearchParams();const detailRef=useRef<HTMLDivElement|null>(null);const queueRef=useRef<HTMLDivElement|null>(null)
  const sportMap=useMemo(()=>new Map(sports.map(s=>[s.id,s])),[sports]);const teamMap=useMemo(()=>new Map(teams.map(t=>[t.id,t])),[teams]);const allVarsityTeams=useMemo(()=>teams.filter(t=>t.active!==false&&(!t.level||t.level.toLowerCase().trim()==='varsity')).sort((a,b)=>(a.school?.school_name||a.team_name).localeCompare(b.school?.school_name||b.team_name)),[teams])
  const requestedSeason=searchParams.get('season')||'';const requestedTeam=searchParams.get('team')||''
  const[teamId,setTeamId]=useState(requestedTeam);const[seasonId,setSeasonId]=useState(requestedSeason||seasons.find(s=>s.is_active)?.id||seasons[0]?.id||'');const[arbiterUrl,setArbiterUrl]=useState('');const[teamUrls,setTeamUrls]=useState<Record<string,string>>({});const[schoolUrls,setSchoolUrls]=useState<Record<string,string>>({});const[loading,setLoading]=useState(false);const[applying,setApplying]=useState(false);const[itemApplying,setItemApplying]=useState<string|null>(null);const[batchApplying,setBatchApplying]=useState(false);const[batchAddingConfirmed,setBatchAddingConfirmed]=useState(false);const[discoveringSchool,setDiscoveringSchool]=useState(false);const[error,setError]=useState<string|null>(null);const[result,setResult]=useState<CompareResult|null>(null);const[parsedRows,setParsedRows]=useState<ParsedGameRow[]>([]);const[scanMeta,setScanMeta]=useState<{teamName?:string|null;rowCount?:number;sourceUrl?:string}|null>(null);const[applyMessage,setApplyMessage]=useState<string|null>(null);const[mappingMessage,setMappingMessage]=useState<string|null>(null);const[batchMessage,setBatchMessage]=useState<string|null>(null);const[batchRunning,setBatchRunning]=useState(false);const[batchProgress,setBatchProgress]=useState({current:0,total:0});const[batchRows,setBatchRows]=useState<BatchRow[]>([]);const[queueFilter,setQueueFilter]=useState<QueueFilter>('all');const[queueApplying,setQueueApplying]=useState<string|null>(null)
  useEffect(()=>{try{setTeamUrls(JSON.parse(localStorage.getItem(TEAM_URLS_KEY)||'{}'));setSchoolUrls(JSON.parse(localStorage.getItem(SCHOOL_URLS_KEY)||'{}'))}catch{setTeamUrls({});setSchoolUrls({})}},[])
  const selectedSeason=seasons.find(s=>s.id===seasonId)||null;const activeTeamIds=useMemo(()=>new Set(teamSeasons.filter(r=>r.season_id===seasonId&&r.active_for_season===true).map(r=>r.team_id)),[teamSeasons,seasonId]);const seasonTeams=useMemo(()=>allVarsityTeams.filter(team=>{const sport=sportMap.get(team.sport_id);const seasonTypeMatches=!selectedSeason||!sport||sport.season_type===selectedSeason.season_type;const participationKnown=teamSeasons.some(r=>r.team_id===team.id&&r.season_id===seasonId);return seasonTypeMatches&&(!participationKnown||activeTeamIds.has(team.id))}),[allVarsityTeams,sportMap,selectedSeason,teamSeasons,seasonId,activeTeamIds]);const selectedTeam=seasonTeams.find(t=>t.id===teamId)||null;const selectedSport=selectedTeam?sportMap.get(selectedTeam.sport_id)||null:null;const knownTeamsForSeason=useMemo(()=>seasonTeams.filter(team=>!!teamUrls[team.id]||!!(team.school?.id&&schoolUrls[team.school.id])),[seasonTeams,teamUrls,schoolUrls])
  useEffect(()=>{if(!teamId)return;const t=seasonTeams.find(x=>x.id===teamId);if(!t)return;const remembered=teamUrls[teamId]||(t.school?.id?schoolUrls[t.school.id]:'')||'';if(remembered&&!arbiterUrl)setArbiterUrl(remembered)},[teamId,seasonTeams,teamUrls,schoolUrls,arbiterUrl])
  function resetResults(){setResult(null);setParsedRows([]);setScanMeta(null);setError(null);setApplyMessage(null)}
  function saveUrlMaps(nextTeamUrls:Record<string,string>,nextSchoolUrls:Record<string,string>){setTeamUrls(nextTeamUrls);setSchoolUrls(nextSchoolUrls);localStorage.setItem(TEAM_URLS_KEY,JSON.stringify(nextTeamUrls));localStorage.setItem(SCHOOL_URLS_KEY,JSON.stringify(nextSchoolUrls))}
  function rememberDirectMapping(team:TeamRecord,url:string){const nextTeamUrls={...teamUrls,[team.id]:url};const schoolUrl=schoolUrlFromScheduleUrl(url);const nextSchoolUrls={...schoolUrls};if(team.school?.id&&schoolUrl)nextSchoolUrls[team.school.id]=schoolUrl;saveUrlMaps(nextTeamUrls,nextSchoolUrls)}
  function candidateMatchesSport(candidate:any,sport:Sport){const wanted=normalizeSport(sport.sport_name);const values=[candidate.sectionXSportName,candidate.displayName,candidate.sportName,candidate.gender&&candidate.sportName?`${candidate.gender} ${candidate.sportName}`:null].filter(Boolean).map(normalizeSport);return values.some(v=>v===wanted||v.includes(wanted))}
  async function discoverSchoolMappings(team:TeamRecord,rawSchoolUrl:string){if(!team.school?.id||!rawSchoolUrl)return 0;const response=await fetch('/api/admin/arbiter-school-sync',{method:'POST',credentials:'include',headers:{'Content-Type':'application/json'},body:JSON.stringify({url:rawSchoolUrl})});const discovery=await response.json();if(!response.ok||!discovery.success)throw new Error(discovery.error||'Could not discover Arbiter teams for this school.');const additions:Record<string,string>={};for(const internal of allVarsityTeams.filter(x=>x.school?.id===team.school?.id)){const sport=sportMap.get(internal.sport_id);if(!sport)continue;const candidate=(discovery.teams||[]).find((item:any)=>item.isVarsity&&item.scheduleUrl&&candidateMatchesSport(item,sport));if(candidate?.scheduleUrl)additions[internal.id]=candidate.scheduleUrl}saveUrlMaps({...teamUrls,...additions},{...schoolUrls,[team.school.id]:rawSchoolUrl});return Object.keys(additions).length}
  async function resolveScheduleUrl(team:TeamRecord,sport:Sport,rawUrl:string){const trimmed=rawUrl.trim();if(/\/Teams\/Schedule\/\d+/i.test(trimmed))return trimmed;const response=await fetch('/api/admin/arbiter-school-sync',{method:'POST',credentials:'include',headers:{'Content-Type':'application/json'},body:JSON.stringify({url:trimmed})});const discovery=await response.json();if(!response.ok||!discovery.success)throw new Error(discovery.error||'Could not discover schedules from that Arbiter school URL.');const candidate=(discovery.teams||[]).find((item:any)=>item.isVarsity&&item.scheduleUrl&&candidateMatchesSport(item,sport));if(!candidate?.scheduleUrl)throw new Error(`Arbiter did not publish a matching varsity ${sport.sport_name} schedule for ${team.school?.school_name||team.team_name}.`);return candidate.scheduleUrl as string}
  function teamRecordsForSport(team:TeamRecord){return teams.filter(c=>c.sport_id===team.sport_id).map(c=>({id:c.id,team_name:c.team_name,school_name:c.school?.school_name||'',slug:c.school?.slug||'',aliases:c.school?.alias?[c.school.alias]:[]}))}
  async function performScan(team:TeamRecord,season:Season,rawUrl:string):Promise<ScanOutput>{const sport=sportMap.get(team.sport_id);if(!sport)throw new Error('Could not determine the selected sport.');const resolvedUrl=await resolveScheduleUrl(team,sport,rawUrl);const arbiterResponse=await fetch('/api/admin/arbiter-team',{method:'POST',credentials:'include',headers:{'Content-Type':'application/json'},body:JSON.stringify({url:resolvedUrl})});const arbiter=await arbiterResponse.json();if(!arbiterResponse.ok||!arbiter.success)throw new Error(arbiter.error||`Arbiter fetch failed (${arbiterResponse.status})`);let rows=parseArbiterSchedule(arbiter.arbiterText,{teams:teamRecordsForSport(team),sourceTeamId:team.id,defaultDate:new Date().toISOString().slice(0,10),defaultSportId:team.sport_id,defaultSeasonId:season.id,year:season.year});rows=rows.map(row=>({...row,approved:row.confidence!=='Low'}));const comparableRows=rows.filter(row=>row.confidence!=='Low'&&row.game_date);const games=comparableRows.map(row=>({season_id:season.id,sport_id:row.sport_id||team.sport_id,game_date:row.game_date,game_time:row.game_time,location:row.location||null,home_team_id:row.home_team_id||null,away_team_id:row.away_team_id||null,external_home_name:row.external_home_name||null,external_away_name:row.external_away_name||null,home_score:row.home_score,away_score:row.away_score,status:row.status,rescheduled_date:row.rescheduled_date,game_number:row.game_number,neutral_site:row.neutral_site,event_name:row.event_name,notes:row.notes||null,parser_confidence:row.confidence,source:'arbiter',verification_status:'Reported'}));const compareResponse=await fetch('/api/admin/schedule-sync',{method:'POST',credentials:'include',headers:{'Content-Type':'application/json'},body:JSON.stringify({team_id:team.id,season_id:season.id,sport_id:team.sport_id,games})});const comparison=await compareResponse.json();if(!compareResponse.ok||!comparison.success)throw new Error(comparison.error||`Comparison failed (${compareResponse.status})`);syncComparisonCounts(comparison);return{comparison,rows,resolvedUrl,arbiterTeamName:arbiter.teamName}}
  async function runScan(){if(!selectedTeam||!selectedSeason||!selectedSport||!arbiterUrl.trim())return;setLoading(true);setError(null);setApplyMessage(null);setMappingMessage(null);setResult(null);try{const output=await performScan(selectedTeam,selectedSeason,arbiterUrl);setParsedRows(output.rows);setScanMeta({teamName:output.arbiterTeamName,rowCount:output.rows.length,sourceUrl:output.resolvedUrl});setResult(output.comparison);setArbiterUrl(output.resolvedUrl);rememberDirectMapping(selectedTeam,output.resolvedUrl);const schoolUrl=schoolUrlFromScheduleUrl(output.resolvedUrl);if(schoolUrl&&selectedTeam.school?.id&&!schoolUrls[selectedTeam.school.id]){setDiscoveringSchool(true);try{const count=await discoverSchoolMappings(selectedTeam,schoolUrl);setMappingMessage(`Remembered ${count} published varsity Arbiter team link${count===1?'':'s'} for ${selectedTeam.school.school_name}.`)}catch(e:any){setMappingMessage(`This team URL was remembered. School-wide discovery can be retried later: ${e?.message||'unknown error'}`)}finally{setDiscoveringSchool(false)}}}catch(e:any){setError(e?.message||'Could not scan this schedule.')}finally{setLoading(false)}}
  async function publishForTeam(sourceTeamId:string,games:any[]){const response=await fetch('/api/admin/games',{method:'POST',credentials:'include',headers:{'Content-Type':'application/json'},body:JSON.stringify({games,import_team_id:sourceTeamId,import_source:'arbiter'})});const publish=await response.json();if(!response.ok||publish?.skipped>0||publish?.errors?.length)throw new Error(publish?.error||publish?.errors?.join('; ')||`Sync apply failed (${response.status})`);return publish}
  async function publishGames(games:any[],message:string){if(!selectedTeam)return;await publishForTeam(selectedTeam.id,games);setApplyMessage(message)}
  async function applyVerifiedUpdates(updates:any[]){const response=await fetch('/api/admin/schedule-sync/apply-verified',{method:'POST',credentials:'include',headers:{'Content-Type':'application/json'},body:JSON.stringify({updates})});const payload=await response.json();if(!response.ok||!payload?.success)throw new Error(payload?.error||`Verified update failed (${response.status})`);return payload}
  async function applySafeSync(){if(!result||!selectedTeam||!selectedSeason)return;if(result.apply_allowed===false){setError('This scan is safety-blocked. Re-scan or review the warnings before applying anything.');return}const safeUpdates=result.diffs.filter(d=>d.safe&&d.kind!=='unchanged'&&d.incoming&&d.existing_game_id);if(!safeUpdates.length)return;if(!window.confirm(`Apply ${safeUpdates.length} verified time/status update${safeUpdates.length===1?'':'s'}?\n\nNew games, venue changes, reschedules, removals and conflicts will NOT be included.`))return;setApplying(true);setError(null);setApplyMessage(null);try{const updates=safeUpdates.map(diff=>({id:diff.existing_game_id,game_time:diff.incoming?.game_time??null,status:diff.incoming?.status??'Scheduled',source_team_id:selectedTeam.id,source_team_ids:diff.cross_source_team_ids?.length?diff.cross_source_team_ids:[selectedTeam.id],season_id:selectedSeason.id,sport_id:selectedTeam.sport_id}));const verified=await applyVerifiedUpdates(updates);setApplyMessage(`Verified ${verified.applied} update${verified.applied===1?'':'s'} by database read-back. Re-scan now to confirm the schedule is clean.`)}catch(e:any){setError(e?.message||'Could not apply schedule changes.')}finally{setApplying(false)}}
  async function applyOneDiff(diff:DiffRow){if(!selectedTeam||!selectedSeason||!diff.incoming)return;const isNew=diff.kind==='new'||diff.kind==='external_review';const crossConflict=diff.new_confidence==='cross_source_conflict'||diff.reconciliation_status==='source_conflict';const waiting=diff.reconciliation_status==='single_source';const confirmedExisting=!!diff.existing_game_id&&diff.safe&&diff.reconciliation_status==='two_source_agree'&&isTimeStatusOnlyDiff(diff)&&diff.kind!=='unchanged';const isManualExisting=!!diff.existing_game_id&&['date_changed','location_changed','details_changed'].includes(diff.kind)&&!diff.reconciliation_required;if(crossConflict||waiting||(!isNew&&!isManualExisting&&!confirmedExisting))return;const confirmedNew=diff.kind==='new'&&diff.new_confidence==='confirmed';const action=confirmedExisting?'apply this two-source confirmed update':isNew?(confirmedNew?'add this cross-source confirmed game':'add this fresh game'):'apply this reviewed change';if(!window.confirm(`Are you sure you want to ${action}?\n\nThis only affects this one item.`))return;setItemApplying(diff.key);setError(null);setApplyMessage(null);try{if(confirmedExisting){const verified=await applyVerifiedUpdates([{id:diff.existing_game_id,game_time:diff.incoming?.game_time??null,status:diff.incoming?.status??'Scheduled',source_team_ids:diff.cross_source_team_ids||[],season_id:selectedSeason.id,sport_id:selectedTeam.sport_id}]);setApplyMessage(`Applied and read-back verified ${verified.applied} two-source update. Run Scan All again to confirm both schedules are clean.`)}else{const game={...(diff.existing_game_id?{id:diff.existing_game_id}:{}),...diff.incoming,season_id:selectedSeason.id,sport_id:selectedTeam.sport_id,source:'arbiter',verification_status:'Reported'};await publishGames([game],isNew?'Game added. Re-scan the season to confirm both sides now match.':'Reviewed change applied. Re-scan this team to confirm it now matches.')}}catch(e:any){setError(e?.message||'Could not apply this item.')}finally{setItemApplying(null)}}
  function applyCrossSourceEvidence(rows:BatchRow[]){type NewEvidence={row:BatchRow;diff:DiffRow;sportId:string;sourceTeamId:string;pair:string;date:string};const newEvidence:NewEvidence[]=[];for(const row of rows){const team=teamMap.get(row.teamId);if(!team||!row.output)continue;for(const diff of row.output.comparison.diffs){if(diff.kind!=='new'||!diff.incoming?.home_team_id||!diff.incoming?.away_team_id||!diff.incoming?.game_date)continue;const pair=pairKey(diff.incoming,team.sport_id);if(pair)newEvidence.push({row,diff,sportId:team.sport_id,sourceTeamId:row.teamId,pair,date:diff.incoming.game_date})}}const byPair=new Map<string,NewEvidence[]>();for(const item of newEvidence){const list=byPair.get(item.pair)||[];list.push(item);byPair.set(item.pair,list)}for(const group of byPair.values()){const sourceIds=new Set(group.map(x=>x.sourceTeamId));const byDate=new Map<string,NewEvidence[]>();for(const item of group){const list=byDate.get(item.date)||[];list.push(item);byDate.set(item.date,list)}const confirmedItems=new Set<NewEvidence>();for(const bucket of byDate.values()){const bucketSources=new Set(bucket.map(x=>x.sourceTeamId));const first=bucket[0]?.diff.incoming;const participantIds=new Set([first?.home_team_id,first?.away_team_id].filter(Boolean));const confirmed=participantIds.size===2&&[...participantIds].every(id=>bucketSources.has(id as string));if(confirmed){for(const item of bucket){item.diff.new_confidence='confirmed';item.diff.cross_source_count=bucketSources.size;item.diff.cross_source_team_ids=[...bucketSources];item.diff.note='Both Section X Arbiter schedules independently confirm this missing game on the same date. It may be batch-added only after explicit confirmation.';confirmedItems.add(item)}}}if(sourceIds.size>=2){const unresolved=group.filter(item=>!confirmedItems.has(item));const unresolvedDates=new Set(unresolved.map(x=>x.date));if(unresolved.length>=2&&unresolvedDates.size>=2){for(const item of unresolved){item.diff.new_confidence='cross_source_conflict';item.diff.cross_source_count=sourceIds.size;item.diff.cross_source_team_ids=[...sourceIds];item.diff.note='The two Section X Arbiter sources show this matchup on different dates. Do not add either version until the schools agree.'}}}}
    type ExistingEvidence={row:BatchRow;diff:DiffRow;sourceTeamId:string};const byExistingGame=new Map<string,ExistingEvidence[]>();for(const row of rows){if(!row.output)continue;for(const diff of row.output.comparison.diffs){if(!diff.existing_game_id||!diff.incoming?.home_team_id||!diff.incoming?.away_team_id||!isTimeStatusOnlyDiff(diff))continue;const list=byExistingGame.get(diff.existing_game_id)||[];list.push({row,diff,sourceTeamId:row.teamId});byExistingGame.set(diff.existing_game_id,list)}}for(const group of byExistingGame.values()){const first=group[0]?.diff.incoming;const participantIds=[first?.home_team_id,first?.away_team_id].filter(Boolean)as string[];if(participantIds.length!==2)continue;const sourceMap=new Map<string,ExistingEvidence>();for(const item of group){if(participantIds.includes(item.sourceTeamId)&&!sourceMap.has(item.sourceTeamId))sourceMap.set(item.sourceTeamId,item)}const observations:SourceObservation[]=[...sourceMap.values()].map(item=>({team_id:item.sourceTeamId,team_name:item.row.teamName,game_time:item.diff.incoming?.game_time??null,status:item.diff.incoming?.status??null}));const changed=group.filter(item=>item.diff.kind!=='unchanged');if(!changed.length)continue;if(sourceMap.size<2){for(const item of changed){item.diff.safe=false;item.diff.reconciliation_status='single_source';item.diff.cross_source_count=sourceMap.size;item.diff.cross_source_team_ids=[...sourceMap.keys()];item.diff.source_observations=observations;item.diff.note='This internal Section X time/status change is visible from only one fresh team source. Waiting for the opponent schedule before any write is allowed.'}continue}const relevant=participantIds.map(id=>sourceMap.get(id)).filter(Boolean)as ExistingEvidence[];const signatures=new Set(relevant.map(item=>observationSignature(item.diff.incoming)));const sourceIds=participantIds.filter(id=>sourceMap.has(id));const sourceSummary=observations.map(obs=>`${obs.team_name}: ${formatTime(obs.game_time)} / ${obs.status||'Scheduled'}`).join(' · ');if(signatures.size===1){for(const item of relevant){item.diff.reconciliation_status='two_source_agree';item.diff.cross_source_count=2;item.diff.cross_source_team_ids=sourceIds;item.diff.source_observations=observations;if(item.diff.kind!=='unchanged')item.diff.safe=true;item.diff.note=item.diff.kind==='unchanged'?'Both fresh Section X sources agree with this observation.':`Both fresh Section X sources independently agree on this time/status change. Eligible for verified database write. ${sourceSummary}`}}else{for(const item of relevant){item.diff.safe=false;item.diff.reconciliation_status='source_conflict';item.diff.cross_source_count=2;item.diff.cross_source_team_ids=sourceIds;item.diff.source_observations=observations;item.diff.note=`Fresh Section X sources disagree. ${sourceSummary}. No database write is allowed until the sources agree.`}}}
    return rows.map(row=>{const c=row.output?.comparison;if(!c)return row;const summary=syncComparisonCounts(c);const blocked=c.apply_allowed===false;const status:BatchStatus=blocked?'blocked':summary.sourceConflicts>0?'conflict':summary.otherReview>0?'review':summary.singleSourceNew>0?'new':summary.confirmedNew>0?'confirmed':summary.verifiedUpdates>0?'updated':'clean';return{...row,status,unchanged:summary.unchanged,updates:summary.verifiedUpdates,confirmedNew:summary.confirmedNew,singleSourceNew:summary.singleSourceNew,conflicts:summary.sourceConflicts,review:summary.otherReview}})}
  async function scanAllKnown(){if(!selectedSeason||knownTeamsForSeason.length===0)return;setBatchRunning(true);setBatchRows([]);setBatchMessage(null);setQueueFilter('all');setBatchProgress({current:0,total:knownTeamsForSeason.length});const collected:BatchRow[]=[];for(let i=0;i<knownTeamsForSeason.length;i+=1){const team=knownTeamsForSeason[i];const sport=sportMap.get(team.sport_id);const rawUrl=teamUrls[team.id]||(team.school?.id?schoolUrls[team.school.id]:'')||'';setBatchProgress({current:i+1,total:knownTeamsForSeason.length});try{const output=await performScan(team,selectedSeason,rawUrl);rememberDirectMapping(team,output.resolvedUrl);const summary=summarizeDiffs(output.comparison.diffs);collected.push({teamId:team.id,teamName:team.school?.school_name||team.team_name,sportName:sport?.sport_name||team.team_name,status:output.comparison.apply_allowed===false?'blocked':'clean',unchanged:summary.unchanged,updates:summary.verifiedUpdates,confirmedNew:summary.confirmedNew,singleSourceNew:summary.singleSourceNew,conflicts:summary.sourceConflicts,review:summary.otherReview,message:output.comparison.apply_allowed===false?(output.comparison.safety_reasons||[]).join(' '):undefined,output})}catch(e:any){collected.push({teamId:team.id,teamName:team.school?.school_name||team.team_name,sportName:sport?.sport_name||team.team_name,status:'failed',unchanged:0,updates:0,confirmedNew:0,singleSourceNew:0,conflicts:0,review:0,message:e?.message||'Scan failed'})}setBatchRows([...collected]);await wait(250)}const reconciled=applyCrossSourceEvidence(collected);setBatchRows(reconciled);setBatchMessage(`Fresh-source reconciliation complete across ${reconciled.filter(row=>row.output).length} team schedules. Scan All made no database changes.`);setBatchRunning(false)}
  async function applyAllVerifiedUpdates(){if(!selectedSeason||batchRunning||batchApplying||batchAddingConfirmed)return;const unique=new Map<string,{teamId:string;diff:DiffRow;sportId:string}>();for(const row of batchRows){const team=teamMap.get(row.teamId);if(!team||!row.output)continue;for(const diff of row.output.comparison.diffs){if(diff.safe&&diff.kind!=='unchanged'&&diff.incoming&&diff.existing_game_id&&!unique.has(diff.existing_game_id))unique.set(diff.existing_game_id,{teamId:row.teamId,diff,sportId:team.sport_id})}}if(!unique.size)return;if(!window.confirm(`Apply ${unique.size} verified time/status update${unique.size===1?'':'s'} across the season?\n\nInternal games require two fresh Section X sources to agree. Exact external-opponent updates may use their single Section X source. No dates, venues, removals or conflicts are included.`))return;setBatchApplying(true);setBatchMessage(null);setError(null);try{const updates=[...unique.values()].map(item=>({id:item.diff.existing_game_id,game_time:item.diff.incoming?.game_time??null,status:item.diff.incoming?.status??'Scheduled',source_team_id:item.teamId,source_team_ids:item.diff.cross_source_team_ids?.length?item.diff.cross_source_team_ids:[item.teamId],season_id:selectedSeason.id,sport_id:item.sportId}));const verified=await applyVerifiedUpdates(updates);setBatchMessage(`Applied and read-back verified ${verified.applied} update${verified.applied===1?'':'s'}. Run Scan All again; these updates should now disappear.`)}catch(e:any){setError(e?.message||'Could not apply verified season updates.')}finally{setBatchApplying(false)}}
  async function applyQueueVerified(item:QueueItem){if(item.category!=='verified'||!selectedSeason||!item.diff.existing_game_id||!item.diff.incoming)return;const team=teamMap.get(item.row.teamId);if(!team)return;const details=gameDetails(item.diff.incoming);if(!window.confirm(`Apply this verified update?\n\n${details?.away||'Away'} at ${details?.home||'Home'}\n${item.diff.incoming?.game_date||''} · ${details?.time||''}\n\nOnly the verified time/status fields will be written and read back.`))return;setQueueApplying(item.key);setError(null);try{const payload={id:item.diff.existing_game_id,game_time:item.diff.incoming?.game_time??null,status:item.diff.incoming?.status??'Scheduled',source_team_id:item.row.teamId,source_team_ids:item.diff.cross_source_team_ids?.length?item.diff.cross_source_team_ids:[item.row.teamId],season_id:selectedSeason.id,sport_id:team.sport_id};const verified=await applyVerifiedUpdates([payload]);setBatchMessage(`Applied and read-back verified ${verified.applied} update. Run Scan All again to refresh the command center.`)}catch(e:any){setError(e?.message||'Could not apply this verified update.')}finally{setQueueApplying(null)}}
  async function addAllConfirmedNewGames(){if(!selectedSeason||batchRunning||batchApplying||batchAddingConfirmed)return;const unique=new Map<string,{sportId:string;diff:DiffRow;sourceTeamIds:string[]}>();for(const row of batchRows){const team=teamMap.get(row.teamId);if(!team||!row.output)continue;for(const diff of row.output.comparison.diffs){if(diff.kind!=='new'||diff.new_confidence!=='confirmed'||!diff.incoming)continue;const key=datedPairKey(diff.incoming,team.sport_id);if(!key||unique.has(key))continue;const sources=(diff.cross_source_team_ids||[]).filter(Boolean);unique.set(key,{sportId:team.sport_id,diff,sourceTeamIds:sources.length?sources:[row.teamId]})}}if(!unique.size)return;if(!window.confirm(`Add ${unique.size} two-source confirmed new game${unique.size===1?'':'s'} to Section X Scoreboard?\n\nSingle-source games and conflicts are NOT included.`))return;setBatchAddingConfirmed(true);setBatchMessage(null);setError(null);try{for(const item of unique.values()){const game={...item.diff.incoming,season_id:selectedSeason.id,sport_id:item.sportId,source:'arbiter',verification_status:'Reported'};const sources=[...new Set(item.sourceTeamIds)];await publishForTeam(sources[0],[game]);for(const sourceTeamId of sources.slice(1))await publishForTeam(sourceTeamId,[game])}setBatchMessage(`Added ${unique.size} two-source confirmed game${unique.size===1?'':'s'} and recorded both Arbiter sources. Run Scan All again.`)}catch(e:any){setError(e?.message||'Could not add all confirmed games.')}finally{setBatchAddingConfirmed(false)}}
  function openBatchReview(row:BatchRow){if(!row.output)return;const team=seasonTeams.find(t=>t.id===row.teamId);const comparison={...row.output.comparison,diffs:row.output.comparison.diffs.map(diff=>({...diff,changes:[...diff.changes],source_observations:diff.source_observations?[...diff.source_observations]:undefined}))};syncComparisonCounts(comparison);setTeamId(row.teamId);setArbiterUrl(row.output.resolvedUrl);setResult(comparison);setParsedRows(row.output.rows);setScanMeta({teamName:row.output.arbiterTeamName,rowCount:row.output.rows.length,sourceUrl:row.output.resolvedUrl});setError(null);setApplyMessage(null);setMappingMessage(team?`Opened ${row.teamName} ${row.sportName} from the season scan. Detail counts use the same post-reconciliation math as the command center.`:null);setTimeout(()=>detailRef.current?.scrollIntoView({behavior:'smooth',block:'start'}),50)}
  function teamLabel(id:string|null|undefined){if(!id)return null;const team=teamMap.get(id);return team?.school?.school_name||team?.team_name||'Section X team'}
  function gameDetails(game:any){if(!game)return null;const home=teamLabel(game.home_team_id)||game.external_home_name||'TBD';const away=teamLabel(game.away_team_id)||game.external_away_name||'TBD';return{home,away,time:formatTime(game.game_time),location:game.location||'TBD',status:game.status||'Scheduled'}}
  function chooseFilter(filter:QueueFilter){setQueueFilter(filter);setTimeout(()=>queueRef.current?.scrollIntoView({behavior:'smooth',block:'start'}),30)}

  const resultSummary=result?summarizeDiffs(result.diffs):null;const safeUpdateCount=resultSummary?.verifiedUpdates||0;const confirmedNewCount=resultSummary?.confirmedNew||0;const singleSourceNewCount=resultSummary?.singleSourceNew||0;const crossConflictCount=resultSummary?.sourceConflicts||0;const waitingSecondSourceCount=resultSummary?.waitingSecondSource||0;const dateRescheduleCount=resultSummary?.dateReschedule||0;const venueReviewCount=resultSummary?.venue||0;const possibleRemovedCount=resultSummary?.possibleRemoved||0;const matchDetailsCount=resultSummary?.matchDetails||0;const twoSourceUpdateCount=result?new Set(result.diffs.filter(d=>d.reconciliation_status==='two_source_agree'&&d.safe&&d.kind!=='unchanged'&&d.existing_game_id).map(d=>d.existing_game_id)).size:0;const unchangedCount=resultSummary?.unchanged||0;const manualReviewCount=resultSummary?.otherReview||0;const applyAllowed=result?.apply_allowed!==false
  const confirmedKeys=new Set<string>(),singleKeys=new Set<string>(),conflictKeys=new Set<string>(),verifiedUpdateKeys=new Set<string>(),waitingKeys=new Set<string>(),dateKeys=new Set<string>(),venueKeys=new Set<string>(),removalKeys=new Set<string>(),detailsKeys=new Set<string>();const queueMap=new Map<string,QueueItem>()
  for(const row of batchRows){const team=teamMap.get(row.teamId);if(!team||!row.output)continue;for(const diff of row.output.comparison.diffs){const key=issueKey(diff,row.teamId);if(diff.safe&&diff.kind!=='unchanged'&&diff.existing_game_id)verifiedUpdateKeys.add(diff.existing_game_id);if(diff.kind==='new'&&diff.incoming){const exact=datedPairKey(diff.incoming,team.sport_id);const pair=pairKey(diff.incoming,team.sport_id);if(diff.new_confidence==='confirmed'&&exact)confirmedKeys.add(exact);else if(diff.new_confidence==='cross_source_conflict'&&pair)conflictKeys.add(pair);else if(exact)singleKeys.add(exact)}else if(diff.kind==='external_review')singleKeys.add(`${row.teamId}|external|${diff.incoming?.game_date}|${diff.key}`);if(diff.kind==='conflict'||diff.reconciliation_status==='source_conflict')conflictKeys.add(key);if(!diff.safe&&diff.reconciliation_status==='single_source'&&diff.kind!=='new'&&diff.kind!=='external_review')waitingKeys.add(key);else if(!diff.safe&&diff.kind==='date_changed'&&diff.reconciliation_status!=='source_conflict')dateKeys.add(key);else if(!diff.safe&&diff.kind==='location_changed'&&diff.reconciliation_status!=='source_conflict')venueKeys.add(key);else if(!diff.safe&&diff.kind==='possible_removed')removalKeys.add(key);else if(!diff.safe&&!['new','external_review','unchanged','date_changed','location_changed','possible_removed'].includes(diff.kind)&&diff.reconciliation_status!=='source_conflict')detailsKeys.add(key);const category=queueCategory(diff);if(category){const qKey=category==='confirmed_new'?`${category}|${datedPairKey(diff.incoming,team.sport_id)||key}`:`${category}|${key}`;if(!queueMap.has(qKey))queueMap.set(qKey,{key:qKey,category,row,diff})}}}
  const queueItems=[...queueMap.values()];const reviewCategories=new Set<QueueCategory>(['waiting','date','venue','removed','details']);const visibleQueueItems=queueItems.filter(item=>queueFilter==='all'||queueFilter==='review'?queueFilter==='all'||reviewCategories.has(item.category):item.category===queueFilter);const rowHasFilter=(row:BatchRow)=>{if(queueFilter==='all')return true;if(queueFilter==='clean')return row.status==='clean';if(queueFilter==='blocked')return row.status==='blocked';if(queueFilter==='failed')return row.status==='failed';if(queueFilter==='verified')return row.updates>0;if(queueFilter==='confirmed_new')return row.confirmedNew>0;if(queueFilter==='single_source')return row.singleSourceNew>0;if(queueFilter==='conflict')return row.conflicts>0;if(queueFilter==='review')return row.review>0;return!!row.output?.comparison.diffs.some(d=>queueCategory(d)===queueFilter)};const visibleRows=batchRows.filter(rowHasFilter)
  const batchTotals=batchRows.reduce((acc,row)=>{if(row.status==='clean')acc.cleanTeams+=1;if(row.status==='blocked')acc.blocked+=1;if(row.status==='failed')acc.failed+=1;return acc},{cleanTeams:0,blocked:0,failed:0});const uniqueReviewTotal=waitingKeys.size+dateKeys.size+venueKeys.size+removalKeys.size+detailsKeys.size;const batchBusy=batchRunning||batchApplying||batchAddingConfirmed

  return <div className="p-4 md:p-6 max-w-7xl mx-auto">
    <div className="flex flex-col lg:flex-row lg:items-end lg:justify-between gap-3 mb-5"><div><div className="text-xs font-bold uppercase tracking-[.22em] mb-2" style={{color:'#60a5fa'}}>Section X Data Command Center</div><h1 className="text-3xl font-bold" style={{fontFamily:'var(--font-display)'}}>Live Schedule Intelligence</h1><p className="text-sm mt-1" style={{color:'var(--text-secondary)'}}>Scan every mapped varsity schedule, reconcile both sides of each Section X matchup, and write only evidence-backed changes.</p></div><Link href="/admin/schedule-audit" className="text-xs font-bold px-3 py-2 rounded-lg" style={{color:'#93c5fd',border:'1px solid rgba(96,165,250,.25)',background:'rgba(59,130,246,.07)'}}>Open Schedule Audit →</Link></div>
    <div className="rounded-xl p-4 mb-5" style={{background:'rgba(74,222,128,.045)',border:'1px solid rgba(74,222,128,.18)'}}><div className="flex flex-col md:flex-row md:items-center md:justify-between gap-2"><div><div className="font-black text-sm" style={{color:'#86efac'}}>WRITE POLICY: EVIDENCE FIRST</div><div className="text-xs mt-1" style={{color:'var(--text-secondary)'}}>Scan All is read-only. Internal Section X time/status updates require both fresh team sources to agree. Source disagreements never get a write button.</div></div><div className="text-[10px] font-black uppercase px-3 py-2 rounded-lg whitespace-nowrap" style={{color:'#86efac',background:'rgba(74,222,128,.08)',border:'1px solid rgba(74,222,128,.18)'}}>Reconciliation Guard Active</div></div></div>
    <div className="rounded-xl p-4 mb-5" style={{background:'var(--bg-card)',border:'1px solid var(--border)'}}>
      <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-3"><div><div className="font-bold" style={{fontFamily:'var(--font-display)'}}>Season-wide command scan</div><div className="text-xs mt-1" style={{color:'var(--text-secondary)'}}>{knownTeamsForSeason.length} of {seasonTeams.length} active {selectedSeason?.name||'season'} varsity teams have an Arbiter route.</div></div><div className="flex gap-2 flex-wrap"><button className="btn-primary whitespace-nowrap" onClick={scanAllKnown} disabled={batchBusy||knownTeamsForSeason.length===0}>{batchRunning?`Scanning ${batchProgress.current}/${batchProgress.total}...`:`Scan All Active Teams (${knownTeamsForSeason.length})`}</button>{batchRows.length>0&&verifiedUpdateKeys.size>0&&<button className="btn-primary whitespace-nowrap" onClick={()=>chooseFilter('verified')} disabled={batchBusy}>Review Verified Updates ({verifiedUpdateKeys.size})</button>}{batchRows.length>0&&confirmedKeys.size>0&&<button className="whitespace-nowrap px-4 py-2 rounded-lg text-xs font-black uppercase" onClick={addAllConfirmedNewGames} disabled={batchBusy} style={{background:'#16834a',color:'white'}}>Add Confirmed Games ({confirmedKeys.size})</button>}</div></div>
      {batchMessage&&<div className="mt-3 text-xs rounded-lg p-3" style={{color:'#4ade80',background:'rgba(74,222,128,.06)',border:'1px solid rgba(74,222,128,.16)'}}>{batchMessage}</div>}
      {batchRows.length>0&&<div className="mt-4">
        <div className="grid grid-cols-2 md:grid-cols-4 xl:grid-cols-8 gap-2 mb-3"><MetricButton label="Clean Teams" value={batchTotals.cleanTeams} active={queueFilter==='clean'} onClick={()=>chooseFilter('clean')} tone="good"/><MetricButton label="Verified Updates" value={verifiedUpdateKeys.size} active={queueFilter==='verified'} onClick={()=>chooseFilter('verified')} tone="good"/><MetricButton label="Confirmed New" value={confirmedKeys.size} active={queueFilter==='confirmed_new'} onClick={()=>chooseFilter('confirmed_new')} tone="good"/><MetricButton label="Single Source" value={singleKeys.size} active={queueFilter==='single_source'} onClick={()=>chooseFilter('single_source')} tone="warn"/><MetricButton label="Source Conflicts" value={conflictKeys.size} active={queueFilter==='conflict'} onClick={()=>chooseFilter('conflict')} tone="danger"/><MetricButton label="Review Queue" value={uniqueReviewTotal} active={queueFilter==='review'} onClick={()=>chooseFilter('review')} tone="warn"/><MetricButton label="Blocked" value={batchTotals.blocked} active={queueFilter==='blocked'} onClick={()=>chooseFilter('blocked')} tone="danger"/><MetricButton label="Failed" value={batchTotals.failed} active={queueFilter==='failed'} onClick={()=>chooseFilter('failed')} tone="danger"/></div>
        <div className="rounded-lg p-3 mb-3" style={{background:'rgba(255,255,255,.02)',border:'1px solid rgba(255,255,255,.055)'}}><div className="text-[10px] font-black uppercase tracking-[.16em] mb-2" style={{color:'#93c5fd'}}>Review queue breakdown · click any category</div><div className="grid grid-cols-2 md:grid-cols-5 gap-2"><MiniMetricButton label="Waiting 2nd Source" value={waitingKeys.size} active={queueFilter==='waiting'} onClick={()=>chooseFilter('waiting')}/><MiniMetricButton label="Date / Reschedule" value={dateKeys.size} active={queueFilter==='date'} onClick={()=>chooseFilter('date')}/><MiniMetricButton label="Venue" value={venueKeys.size} active={queueFilter==='venue'} onClick={()=>chooseFilter('venue')}/><MiniMetricButton label="Possible Removed" value={removalKeys.size} active={queueFilter==='removed'} onClick={()=>chooseFilter('removed')}/><MiniMetricButton label="Match / Details" value={detailsKeys.size} active={queueFilter==='details'} onClick={()=>chooseFilter('details')}/></div></div>
        <div ref={queueRef} className="rounded-xl p-3 mb-3 scroll-mt-4" style={{background:'rgba(59,130,246,.035)',border:'1px solid rgba(96,165,250,.13)'}}><div className="flex items-center justify-between gap-3 mb-2"><div><div className="text-xs font-black uppercase tracking-[.14em]" style={{color:'#93c5fd'}}>{queueLabel(queueFilter)}</div><div className="text-[11px] mt-1" style={{color:'var(--text-muted)'}}>{queueFilter==='clean'||queueFilter==='blocked'||queueFilter==='failed'?`${visibleRows.length} team${visibleRows.length===1?'':'s'}`:`${visibleQueueItems.length} unique item${visibleQueueItems.length===1?'':'s'}`}</div></div>{queueFilter!=='all'&&<button onClick={()=>setQueueFilter('all')} className="px-3 py-1.5 rounded-md text-[10px] font-bold uppercase" style={{color:'#93c5fd',border:'1px solid rgba(96,165,250,.2)'}}>Show All</button>}</div>
          {!['clean','blocked','failed'].includes(queueFilter)&&visibleQueueItems.length>0&&<div className="space-y-2 max-h-[520px] overflow-y-auto">{visibleQueueItems.map(item=>{const d=item.diff;const details=gameDetails(d.incoming||d.existing);const gameDate=d.incoming?.game_date||d.existing?.game_date||'No date';const verified=item.category==='verified';const conflict=item.category==='conflict';return <div key={item.key} className="rounded-lg p-3" style={{background:'rgba(255,255,255,.025)',border:`1px solid ${verified?'rgba(74,222,128,.22)':conflict?'rgba(248,113,113,.28)':'rgba(251,191,36,.14)'}`}}><div className="flex flex-col lg:flex-row lg:justify-between gap-3"><div><div className="flex gap-2 items-center flex-wrap"><span className="text-[10px] font-black uppercase" style={{color:verified?'#86efac':conflict?'#fca5a5':'#fbbf24'}}>{queueLabel(item.category)}</span><span className="text-[10px]" style={{color:'var(--text-muted)'}}>{item.row.teamName} · {item.row.sportName}</span></div><div className="font-bold mt-1">{details?`${details.away} at ${details.home}`:'Schedule item'}</div><div className="text-xs mt-1" style={{color:'var(--text-secondary)'}}>{gameDate} · {details?.time||'TBD'} · {details?.status||'Scheduled'}</div></div><div className="flex flex-wrap gap-2 items-start">{d.existing_game_id&&<Link href={`/admin/game-center/${d.existing_game_id}`} className="px-3 py-2 rounded-md text-[10px] font-bold uppercase" style={{color:'#93c5fd',border:'1px solid rgba(96,165,250,.2)'}}>Game Center</Link>}<button onClick={()=>openBatchReview(item.row)} className="px-3 py-2 rounded-md text-[10px] font-bold uppercase" style={{color:'#93c5fd',border:'1px solid rgba(96,165,250,.2)'}}>Open Team Detail</button>{verified&&<button onClick={()=>applyQueueVerified(item)} disabled={queueApplying===item.key||batchBusy} className="px-3 py-2 rounded-md text-[10px] font-black uppercase" style={{background:'#16834a',color:'white',opacity:queueApplying===item.key?0.6:1}}>{queueApplying===item.key?'Applying...':'Apply This Verified Update'}</button>}</div></div>{d.source_observations&&d.source_observations.length>0&&<div className="grid grid-cols-1 md:grid-cols-2 gap-2 mt-3">{d.source_observations.map(obs=><div key={obs.team_id} className="rounded-md p-2 text-xs" style={{background:conflict?'rgba(248,113,113,.055)':'rgba(74,222,128,.045)',border:`1px solid ${conflict?'rgba(248,113,113,.16)':'rgba(74,222,128,.13)'}`}}><strong>{obs.team_name}</strong><div>{formatTime(obs.game_time)} · {obs.status||'Scheduled'}</div></div>)}</div>}{d.changes.length>0&&<div className="grid grid-cols-1 md:grid-cols-3 gap-2 mt-3">{d.changes.map(c=><div key={c.field} className="rounded-md p-2 text-xs" style={{background:'rgba(255,255,255,.02)'}}><strong>{c.field.replaceAll('_',' ')}</strong><div style={{color:'var(--text-muted)'}}>Database: {String(c.before??'—')}</div><div>Fresh: {String(c.after??'—')}</div></div>)}</div>}{d.note&&<div className="text-xs mt-2" style={{color:conflict?'#fca5a5':verified?'#86efac':'var(--text-secondary)'}}>{d.note}</div>}</div>})}</div>}
          {!['clean','blocked','failed'].includes(queueFilter)&&visibleQueueItems.length===0&&<div className="text-xs py-3" style={{color:'var(--text-muted)'}}>No items in this category.</div>}
        </div>
        <div className="space-y-1 max-h-96 overflow-y-auto">{visibleRows.map(row=><div key={row.teamId} className="grid grid-cols-1 md:grid-cols-[1fr_95px_68px_68px_68px_68px_68px_92px] gap-2 rounded-lg px-3 py-2 text-xs items-center" style={{background:'rgba(255,255,255,.025)',border:'1px solid rgba(255,255,255,.05)'}}><div className="font-semibold">{row.teamName} · {row.sportName}</div><div style={{color:statusColor(row.status)}} className="font-bold uppercase">{row.status}</div><div style={{color:'var(--text-muted)'}}>{row.unchanged} clean</div><div style={{color:row.updates?'#4ade80':'var(--text-muted)'}}>{row.updates} verified</div><div style={{color:'#4ade80'}}>{row.confirmedNew} new</div><div style={{color:'#60a5fa'}}>{row.singleSourceNew} single</div><div style={{color:row.conflicts?'#f87171':row.review?'#fbbf24':'var(--text-muted)'}}>{row.conflicts+row.review} review</div><div>{row.output&&row.status!=='clean'?<button onClick={()=>openBatchReview(row)} className="px-2 py-1.5 rounded-md text-[10px] font-bold uppercase" style={{color:'#93c5fd',border:'1px solid rgba(96,165,250,.25)',background:'rgba(59,130,246,.08)'}}>Review →</button>:<span style={{color:'var(--text-muted)'}}>—</span>}</div>{row.message&&<div className="md:col-span-8" style={{color:'#fca5a5'}}>{row.message}</div>}</div>)}</div>
      </div>}
    </div>
    <div ref={detailRef} className="grid grid-cols-1 lg:grid-cols-3 gap-3 mb-4 scroll-mt-4"><div><label className="label">Varsity Team</label><select className="input w-full" value={teamId} onChange={e=>{const id=e.target.value;setTeamId(id);const team=seasonTeams.find(t=>t.id===id);setArbiterUrl(teamUrls[id]||(team?.school?.id?schoolUrls[team.school.id]:'')||'');resetResults()}}><option value="">Select active team</option>{seasonTeams.map(team=><option key={team.id} value={team.id}>{team.school?.school_name||team.team_name} — {sportMap.get(team.sport_id)?.sport_name||team.team_name}</option>)}</select></div><div><label className="label">Season</label><select className="input w-full" value={seasonId} onChange={e=>{setSeasonId(e.target.value);setTeamId('');setArbiterUrl('');setBatchRows([]);setBatchMessage(null);setQueueFilter('all');resetResults()}}>{seasons.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select></div><div><label className="label">Detected Sport</label><div className="input w-full flex items-center" style={{color:selectedSport?'var(--text-primary)':'var(--text-muted)'}}>{selectedSport?.sport_name||'Select a team first'}</div></div></div>
    <div className="mb-4"><label className="label">Arbiter URL</label><div className="flex flex-col md:flex-row gap-2"><input className="input flex-1 font-mono text-sm" placeholder="Team schedule URL or school Teams?entityId= URL" value={arbiterUrl} onChange={e=>{setArbiterUrl(e.target.value);resetResults()}}/><button className="btn-primary whitespace-nowrap" onClick={runScan} disabled={loading||!teamId||!seasonId||!arbiterUrl.trim()}>{loading?'Scanning Arbiter...':result?'Rescan Now':'Scan & Compare'}</button></div></div>
    {discoveringSchool&&<Notice color="#93c5fd">Remembering this school's published varsity Arbiter team links...</Notice>}{mappingMessage&&<Notice color="#93c5fd">{mappingMessage}</Notice>}{error&&<Notice color="#f87171">{error}</Notice>}{applyMessage&&<Notice color="#4ade80">{applyMessage}</Notice>}
    {result&&<><div className="grid grid-cols-2 md:grid-cols-5 gap-3 mb-3"><Metric label="Fresh Games" value={result.incoming_count}/><Metric label="Clean / Unchanged" value={unchangedCount} good/><Metric label="Verified Updates" value={safeUpdateCount} good={safeUpdateCount>0}/><Metric label="Confirmed New" value={confirmedNewCount} good={confirmedNewCount>0}/><Metric label="Source Conflict" value={crossConflictCount} danger={crossConflictCount>0}/></div><div className="rounded-lg p-3 mb-4" style={{background:'rgba(255,255,255,.02)',border:'1px solid rgba(255,255,255,.055)'}}><div className="grid grid-cols-2 md:grid-cols-5 gap-2"><MiniMetric label="Waiting 2nd Source" value={waitingSecondSourceCount}/><MiniMetric label="Date / Reschedule" value={dateRescheduleCount}/><MiniMetric label="Venue" value={venueReviewCount}/><MiniMetric label="Possible Removed" value={possibleRemovedCount}/><MiniMetric label="Match / Details" value={matchDetailsCount}/></div></div>{!applyAllowed&&<Notice color="#fca5a5">SYNC SAFETY LOCK ACTIVE. Nothing can be bulk-applied from this scan.</Notice>}<div className="rounded-xl p-4 mb-4 flex flex-col lg:flex-row lg:items-center lg:justify-between gap-3" style={{background:(manualReviewCount||singleSourceNewCount||crossConflictCount)?'rgba(251,191,36,.055)':'rgba(74,222,128,.055)',border:'1px solid rgba(255,255,255,.08)'}}><div><div className="font-bold text-sm">{twoSourceUpdateCount} two-source update · {confirmedNewCount} confirmed new · {crossConflictCount+manualReviewCount} review</div><div className="text-xs mt-1" style={{color:'var(--text-secondary)'}}>Scan source: {scanMeta?.teamName||selectedTeam?.school?.school_name||selectedTeam?.team_name} · {new Date(result.scanned_at).toLocaleString()}</div></div>{safeUpdateCount>0?<button className="btn-primary" onClick={applySafeSync} disabled={applying||!applyAllowed}>{applying?'Applying...':`Apply Verified Updates (${safeUpdateCount})`}</button>:<div className="text-[10px] font-black uppercase">{manualReviewCount||singleSourceNewCount||crossConflictCount?'Review required · no write available':'Clean · no write needed'}</div>}</div><div className="space-y-3">{result.diffs.slice().sort((a,b)=>Number(a.safe)-Number(b.safe)||a.kind.localeCompare(b.kind)).map(diff=>{const details=gameDetails(diff.incoming);const crossConflict=diff.new_confidence==='cross_source_conflict'||diff.reconciliation_status==='source_conflict';const waiting=diff.reconciliation_status==='single_source';const sourceAgree=diff.reconciliation_status==='two_source_agree';const canAdd=!!diff.incoming&&!crossConflict&&(diff.kind==='new'||diff.kind==='external_review');const canApplyReviewed=!!diff.incoming&&!!diff.existing_game_id&&['date_changed','location_changed','details_changed'].includes(diff.kind)&&!diff.reconciliation_required;const canApplyConfirmed=!!diff.incoming&&!!diff.existing_game_id&&sourceAgree&&diff.safe&&diff.kind!=='unchanged';const confirmed=diff.kind==='new'&&diff.new_confidence==='confirmed';return <div key={diff.key} className="rounded-xl p-4" style={{background:'var(--bg-card)',border:`1px solid ${sourceAgree||confirmed?'rgba(74,222,128,.3)':crossConflict?'rgba(248,113,113,.42)':diff.safe?'var(--border)':'rgba(248,113,113,.28)'}`}}><div className="flex flex-col md:flex-row md:justify-between gap-3"><div><span className="text-xs font-black" style={{color:diffColor(diff)}}>{diffLabel(diff)}</span><div className="font-semibold mt-1">{diff.incoming?.game_date||diff.existing?.game_date||'No date'} · {selectedTeam?.school?.school_name||selectedTeam?.team_name}</div></div><div className="flex gap-2 flex-wrap">{diff.existing_game_id&&<Link href={`/admin/game-center/${diff.existing_game_id}`} className="text-xs font-bold" style={{color:'#93c5fd'}}>Open Game Center →</Link>}{(canAdd||canApplyReviewed||canApplyConfirmed)&&<button onClick={()=>applyOneDiff(diff)} disabled={itemApplying===diff.key} className="px-3 py-2 rounded-lg text-[10px] font-black uppercase" style={{background:sourceAgree||confirmed?'#16834a':'#3156df',color:'white'}}>{itemApplying===diff.key?'Working...':canApplyConfirmed?'Apply Confirmed Update':canAdd?(confirmed?'Add Confirmed Game':diff.kind==='external_review'?'Add External Game':'Add Game'):'Apply This Change'}</button>}</div></div>{diff.source_observations&&diff.source_observations.length>0&&<div className="grid grid-cols-1 md:grid-cols-2 gap-2 mt-3">{diff.source_observations.map(obs=><Detail key={obs.team_id} label={`${obs.team_name} source`} value={`${formatTime(obs.game_time)} · ${obs.status||'Scheduled'}`}/>)}</div>}{details&&diff.kind!=='unchanged'&&<div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-2 mt-3"><Detail label="Matchup" value={`${details.away} at ${details.home}`}/><Detail label="Time" value={details.time}/><Detail label="Location" value={details.location}/><Detail label="Status" value={details.status}/></div>}{diff.changes.length>0&&<div className="grid grid-cols-1 md:grid-cols-3 gap-2 mt-3">{diff.changes.map(c=><Detail key={c.field} label={c.field.replaceAll('_',' ')} value={`${String(c.before??'—')} → ${String(c.after??'—')}`}/>)}</div>}{diff.note&&<div className="text-xs mt-3" style={{color:crossConflict?'#fca5a5':sourceAgree?'#86efac':'var(--text-secondary)'}}>{diff.note}</div>}{waiting&&<div className="text-xs mt-2" style={{color:'#93c5fd'}}>Waiting for the opponent's fresh source before any write.</div>}</div>})}</div></>}
  </div>
}

function Notice({children,color}:{children:React.ReactNode;color:string}){return <div className="rounded-lg p-3 mb-4 text-sm" style={{color,background:'rgba(59,130,246,.06)',border:'1px solid rgba(96,165,250,.16)'}}>{children}</div>}
function Metric({label,value,good=false,danger=false}:{label:string;value:number;good?:boolean;danger?:boolean}){const color=danger?'#f87171':good?'#4ade80':'var(--text-primary)';return <div className="rounded-lg p-3" style={{background:'var(--bg-card)',border:'1px solid var(--border)'}}><div className="text-xs mb-1" style={{color:'var(--text-muted)'}}>{label}</div><div className="text-2xl font-bold" style={{fontFamily:'var(--font-display)',color}}>{value}</div></div>}
function MetricButton({label,value,onClick,active,tone}:{label:string;value:number;onClick:()=>void;active:boolean;tone:'good'|'warn'|'danger'}){const color=tone==='danger'?'#f87171':tone==='warn'?'#fbbf24':'#4ade80';return <button onClick={onClick} className="rounded-lg p-3 text-left transition-transform hover:-translate-y-0.5" style={{background:active?'rgba(59,130,246,.1)':'var(--bg-card)',border:`1px solid ${active?'rgba(96,165,250,.5)':'var(--border)'}`}}><div className="text-xs mb-1" style={{color:'var(--text-muted)'}}>{label}</div><div className="text-2xl font-bold" style={{fontFamily:'var(--font-display)',color}}>{value}</div><div className="text-[9px] mt-1 uppercase" style={{color:active?'#93c5fd':'var(--text-muted)'}}>{active?'Showing':'Click to inspect'}</div></button>}
function MiniMetric({label,value}:{label:string;value:number}){return <div className="rounded-md px-3 py-2" style={{background:value>0?'rgba(251,191,36,.055)':'rgba(255,255,255,.018)',border:'1px solid rgba(255,255,255,.05)'}}><div className="text-[10px]" style={{color:'var(--text-muted)'}}>{label}</div><div className="text-lg font-black" style={{color:value>0?'#fbbf24':'var(--text-secondary)'}}>{value}</div></div>}
function MiniMetricButton({label,value,onClick,active}:{label:string;value:number;onClick:()=>void;active:boolean}){return <button onClick={onClick} className="rounded-md px-3 py-2 text-left" style={{background:active?'rgba(59,130,246,.1)':value>0?'rgba(251,191,36,.055)':'rgba(255,255,255,.018)',border:`1px solid ${active?'rgba(96,165,250,.45)':'rgba(255,255,255,.05)'}`}}><div className="text-[10px]" style={{color:'var(--text-muted)'}}>{label}</div><div className="text-lg font-black" style={{color:value>0?'#fbbf24':'var(--text-secondary)'}}>{value}</div></button>}
function Detail({label,value}:{label:string;value:string}){return <div className="rounded-lg p-2 text-xs" style={{background:'rgba(96,165,250,.045)',border:'1px solid rgba(96,165,250,.12)'}}><div className="font-bold uppercase tracking-wide mb-1" style={{color:'#93c5fd'}}>{label}</div><div style={{color:'#e2e8f0'}}>{value}</div></div>}
